package com.asmj.marketplace.config; import com.asmj.marketplace.security.JwtAuthenticationFilter; import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.web.cors.*; import java.util.*;
import org.springframework.beans.factory.annotation.Value;
@Configuration @EnableMethodSecurity @RequiredArgsConstructor public class SecurityConfig {
@Value("${app.cors.allowed-origins:http://localhost:5173,http://localhost:3000}") private String allowedOrigins;private final JwtAuthenticationFilter jwt; @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain filter(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).cors(c->c.configurationSource(cors())).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(org.springframework.http.HttpMethod.GET,"/api/insurance","/api/insurance/*").permitAll().requestMatchers("/api/auth/**","/api/posts/**","/api/categories/**","/api/rentals/locations","/api/rentals/routes","/api/rentals/quote","/api/rentals/public/vehicles","/api/services","/api/jobs","/api/events","/api/insurance","/swagger-ui/**","/v3/api-docs/**","/ws/**","/error").permitAll().anyRequest().authenticated()).addFilterBefore(jwt,org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class).build();} @Bean CorsConfigurationSource cors(){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(Arrays.stream(allowedOrigins.split(",")).map(String::trim).filter(x->!x.isBlank()).toList());c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","PATCH","OPTIONS"));c.setAllowedHeaders(List.of("*"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}}
